import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {









    @Test
    public void testCreateNumber_Hexadecimal() throws NumberFormatException {
        // Assuming createInteger handles 0x
        Number expected = NumberUtils.createInteger("0x10");
        assertEquals(expected, NumberUtils.createNumber("0x10"));

        Number expectedNeg = NumberUtils.createInteger("-0x10");
        assertEquals(expectedNeg, NumberUtils.createNumber("-0x10"));
    }






















}

