public class NumberUtils_createNumber_TriageGen1Test {













    @Test
    public void testCreateNumber_DecimalTypes() throws NumberFormatException {
        // Float
        assertEquals(1.23f, NumberUtils.createNumber("1.23").floatValue(), 0.001);
        // Double
        assertEquals(1.23d, NumberUtils.createNumber("1.23").doubleValue(), 0.001);
        // BigDecimal
