package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

















    @Test
    public void testCreateNumber_Suffixes() throws NumberFormatException {
        // Long suffix 'L'
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(new BigInteger("123456789012345678901234567890"), NumberUtils.createNumber("123456789012345678901234567890L"));

        // Float suffix 'f'
        assertEquals(1.23f, NumberUtils.createNumber("1.23f").floatValue(), 0.001);

        // Double suffix 'd'
        assertEquals(1.23d, NumberUtils.createNumber("1.23d").doubleValue(), 0.001);
    }














}

