package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {























    @Test
    public void testCreateNumber_AllZerosLogic() throws NumberFormatException {
        // Testing the "allZeros" branch for precision/infinity checks
        // "0.0" should be handled by Float/Double/BigDecimal
        assertEquals(0.0f, NumberUtils.createNumber("0.0").floatValue(), 0.0);
        assertEquals(0.0d, NumberUtils.createNumber("0.0").doubleValue(), 0.0);
        assertEquals(new BigDecimal("0.0"), NumberUtils.createNumber("0.0"));

        // Large exponent zero case
        assertEquals(0.0, NumberUtils.createNumber("0e0").doubleValue(), 0.0);
    }








}

